class RequestBuilder {
    var url: String = ""
    var method: String = "GET"
    val headers = mutableMapOf<String, String>()
    fun header(key: String, value: String) { headers[key] = value }
}

fun request(block: RequestBuilder.() -> Unit): RequestBuilder =
    RequestBuilder().apply(block)

val req = request {
    url = "https://api.example.com/users"
    method = "POST"
    header("Authorization", "Bearer token")
}

@DslMarker
annotation class LayoutDsl

@LayoutDsl
class ColumnScope { fun text(value: String) { /* ... */ } }

@LayoutDsl
class RowScope { fun text(value: String) { /* ... */ } }

fun column(block: ColumnScope.() -> Unit) { ColumnScope().block() }
fun ColumnScope.row(block: RowScope.() -> Unit) { RowScope().block() }

column {
    text("Outer")
    row {
        text("Inner") // only RowScope.text is callable here, not Column's
    }
}
